// Wait for Apify run to complete and get results
const runId = $input.first().json.data.id;
const token = $credentials.apifyApi.token;

// Poll for completion (max 2 minutes)
let completed = false;
let attempts = 0;
const maxAttempts = 24; // 2 minutes with 5 sec intervals

while (!completed && attempts < maxAttempts) {
  const statusResponse = await $http.request({
    method: 'GET',
    url: `https://api.apify.com/v2/actor-runs/${runId}`,
    headers: {
      'Authorization': `Bearer ${token}`
    }
  });

  const status = statusResponse.data.status;

  if (status === 'SUCCEEDED') {
    completed = true;
  } else if (status === 'FAILED' || status === 'ABORTED') {
    throw new Error(`Apify run ${status}`);
  } else {
    await new Promise(resolve => setTimeout(resolve, 5000));
    attempts++;
  }
}

if (!completed) {
  throw new Error('Apify run timed out after 2 minutes');
}

// Get results
const resultsResponse = await $http.request({
  method: 'GET',
  url: `https://api.apify.com/v2/actor-runs/${runId}/dataset/items`,
  headers: {
    'Authorization': `Bearer ${token}`
  }
});

return resultsResponse.data;

// Normalize Apify job data to standard format
const jobs = $input.all();
const normalized = [];

for (const item of jobs) {
  const job = item.json;

  // Extract budget info
  let budget = {
    type: 'unknown',
    amount: null,
    min: null,
    max: null,
    display: 'Not listed'
  };

  if (job.budget) {
    if (job.budget.amount) {
      budget.type = 'fixed';
      budget.amount = parseFloat(job.budget.amount);
      budget.display = `$${budget.amount}`;
    } else if (job.budget.hourlyRate) {
      budget.type = 'hourly';
      budget.min = parseFloat(job.budget.hourlyRate.min || 0);
      budget.max = parseFloat(job.budget.hourlyRate.max || 0);
      budget.display = `$${budget.min}-$${budget.max}/hr`;
    }
  }

  // Generate job ID from URL
  const jobId = job.url ? 'job_' + job.url.split('/').pop() : 'job_' + Date.now();

  normalized.push({
    job_id: jobId,
    title: job.title || 'Untitled Job',
    description: job.description || '',
    url: job.url || '',
    budget: budget,
    skills: job.skills || [],
    posted: job.postedOn || job.createdAt || 'Unknown',
    client: {
      spent: job.client?.totalSpent || 'Unknown',
      rating: job.client?.rating || 'N/A',
      location: job.client?.location || 'Unknown',
      jobs_posted: job.client?.jobsPosted || 'Unknown'
    },
    scraped_at: new Date().toISOString()
  });
}

return normalized;

// Parse Claude response and attach to job data
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const jobData = items[i].json;

  // Get the previous node's data (normalized job)
  const job = $('Parse & Normalize Jobs').item(i).json;

  // Parse Claude's JSON response
  let analysis;
  try {
    // Claude response is in the text field
    const responseText = jobData.text || jobData.content || jobData;

    // Try to extract JSON from response
    const jsonMatch = typeof responseText === 'string' 
      ? responseText.match(/\{[\s\S]*\}/)
      : null;

    if (jsonMatch) {
      analysis = JSON.parse(jsonMatch[0]);
    } else if (typeof responseText === 'object') {
      analysis = responseText;
    } else {
      throw new Error('Could not parse Claude response');
    }
  } catch (error) {
    // Fallback if parsing fails
    analysis = {
      score: 0,
      verdict: 'REJECT',
      job_type: 'unknown',
      breakdown: { skills_match: 0, tech_stack: 0, scope_clarity: 0, timeline_budget: 0 },
      reasoning: 'Analysis failed: ' + error.message,
      red_flags: ['Analysis error'],
      estimated_hours: 0
    };
  }

  results.push({
    ...job,
    analysis: analysis
  });
}

return results;

// Classify job type and determine execution strategy
const items = $input.all();
const enriched = [];

for (const item of items) {
  const job = item.json;
  const analysis = job.analysis;

  // Determine execution tool
  let execution_tool = 'claude_code'; // Default
  let execution_strategy = 'post_acceptance';
  let estimated_credits = 0;
  let estimated_cost = 0;

  if (analysis.job_type === 'web_app') {
    execution_tool = 'deep_agent';
    execution_strategy = 'demo_first';
    estimated_credits = 2500;
    estimated_cost = 2.5;
  } else if (analysis.job_type === 'hybrid') {
    execution_tool = 'both';
    execution_strategy = 'phased';
    estimated_credits = 2500;
    estimated_cost = 2.5;
  }

  // Calculate pricing strategy
  const budget_amount = job.budget.amount || (job.budget.min ? job.budget.min * 40 : 100);
  const suggested_price = calculatePrice(budget_amount, analysis.estimated_hours);

  enriched.push({
    ...job,
    execution: {
      tool: execution_tool,
      strategy: execution_strategy,
      estimated_credits: estimated_credits,
      estimated_cost: estimated_cost
    },
    pricing: {
      budget: budget_amount,
      suggested: suggested_price,
      reasoning: `${Math.round((1 - suggested_price/budget_amount) * 100)}% undercut - competitive`
    }
  });
}

function calculatePrice(budget, hours) {
  if (!budget || budget === 0) {
    return Math.max(50, hours * 30); // $30/hour baseline, min $50
  }

  // 10-15% undercut strategy
  const undercut = budget * 0.88;

  // Floor at $50, round to nearest $5
  return Math.max(50, Math.round(undercut / 5) * 5);
}

return enriched;

// Parse proposal and attach to job data
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const proposalData = items[i].json;
  const job = $('Job Type Classifier').item(i).json;

  // Parse Claude's proposal JSON
  let proposal;
  try {
    const responseText = proposalData.text || proposalData.content || proposalData;
    const jsonMatch = typeof responseText === 'string'
      ? responseText.match(/\{[\s\S]*\}/)
      : null;

    if (jsonMatch) {
      proposal = JSON.parse(jsonMatch[0]);
    } else if (typeof responseText === 'object') {
      proposal = responseText;
    } else {
      throw new Error('Could not parse proposal');
    }
  } catch (error) {
    proposal = {
      proposal: 'Error generating proposal: ' + error.message,
      approach_steps: [],
      timeline: 'TBD',
      price: job.pricing.suggested,
      price_reasoning: 'Default pricing'
    };
  }

  results.push({
    ...job,
    proposal: proposal
  });
}

return results;

// Format jobs for chat presentation
const jobs = $input.all();

// Group by execution tool
const byTool = {
  deep_agent: [],
  claude_code: [],
  both: []
};

for (const item of jobs) {
  const job = item.json;
  byTool[job.execution.tool].push(job);
}

// Create markdown output
let output = `# 🎯 Upwork Job Hunter - Daily Batch\n`;
output += `**Date:** ${new Date().toLocaleDateString()}\n`;
output += `**Qualified Jobs:** ${jobs.length}\n\n`;
output += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

let jobNum = 1;
for (const tool in byTool) {
  const toolJobs = byTool[tool];
  if (toolJobs.length === 0) continue;

  const toolName = tool === 'deep_agent' ? '🌐 DEEP AGENT' : 
                   tool === 'claude_code' ? '💻 CLAUDE CODE' : 
                   '🔀 HYBRID';

  output += `## ${toolName} JOBS (${toolJobs.length})\n\n`;

  for (const job of toolJobs) {
    output += `### [${jobNum}] ${job.title}\n`;
    output += `**Score:** ${job.analysis.score}/100 - ${job.analysis.verdict}\n`;
    output += `**Budget:** ${job.budget.display}\n`;
    output += `**Suggested Price:** $${job.pricing.suggested} (${job.pricing.reasoning})\n`;
    output += `**Est. Time:** ${job.analysis.estimated_hours} hours\n`;
    output += `**Execution:** ${job.execution.tool} (${job.execution.strategy})\n`;

    if (job.execution.estimated_cost > 0) {
      output += `**Cost to Build:** ~$${job.execution.estimated_cost}\n`;
    }

    output += `\n**Proposal:**\n\`\`\`\n${job.proposal.proposal}\n\`\`\`\n\n`;
    output += `**URL:** ${job.url}\n`;
    output += `**Actions:** \`approve_${job.job_id}\` | \`reject_${job.job_id}\` | \`skip_${job.job_id}\`\n\n`;
    output += `─────────────────────────────────────\n\n`;

    jobNum++;
  }
}

return [{
  json: {
    markdown: output,
    job_count: jobs.length,
    jobs: jobs.map(j => j.json),
    timestamp: new Date().toISOString()
  }
}];

