// Handle approval/rejection
const { action, job_id, user_notes } = $json;

if (!action || !job_id) {
  return [{
    json: {
      error: 'Missing action or job_id',
      received: $json
    }
  }];
}

// Route based on action
return [{
  json: {
    action: action,
    job_id: job_id,
    user_notes: user_notes || '',
    route: action === 'approve' ? 'execute' : action === 'reject' ? 'log_rejection' : 'skip',
    timestamp: new Date().toISOString()
  }
}];

// Placeholder for Deep Agent execution
// Currently manual - future: integrate with Abacus API

const job = $json;

return [{
  json: {
    job_id: job.job_id,
    execution_tool: 'deep_agent',
    status: 'manual_execution_required',
    instructions: 'Open Deep Agent at https://deepagent.abacus.ai',
    message: `Build web app for: ${job.title}`,
    timestamp: new Date().toISOString()
  }
}];
